fn deps_of(deps: Map[Str, List[Str]], name: Str) -> List[Str] {
  match deps.get(name) {
    Some(ds) => { return ds },
    None => { return [] },
  }
}

pub fn topo(deps: Map[Str, List[Str]]) -> Result[List[Str], Str] {
  var gathered: List[Str] = []
  for e in deps.entries() {
    gathered = gathered.push(e.key)
    gathered = gathered.concat(e.value)
  }
  let names = gathered.unique().sort()
  var done: Map[Str, Bool] = Map {}
  var order: List[Str] = []
  while order.len() < names.len() {
    let snap = done
    let ready = names.filter(fn(nm) => (not snap.has(nm)) and deps_of(deps, nm).all(fn(d) => snap.has(d)))
    match ready.first() {
      Some(p) => {
        order = order.push(p)
        done = done.set(p, true)
      },
      None => { return Err("cycle") },
    }
  }
  return Ok(order)
}
